import { test } from 'vitest';
import {
  createTournament,
  matchWinner,
  nextTournamentTurn,
  recordTournamentResult,
  TournamentPhase,
} from './rules.ts';
import { FOUR_NAMES, FOUR_CODES, EIGHT_NAMES, EIGHT_CODES } from './tournament.fixture.ts';
